int newDigit = -1;

bool check(set<int> digits, int l, int r, bool useNewDigit) {
    for (int i = l; i <= r; ++i) {
        if (useNewDigit && i == newDigit) {
            continue;
        }
        if (!digits.count(i)) {
            return false;
        }
    }
    return true;
}

void solve() {
    int n, p;
    cin >> n >> p;
    vector<int> a(n + 1);
    set<int> digits;
    for (int i = 1; i <= n; ++i) {
        cin >> a[i];
        digits.insert(a[i]);
    }
    if (digits.size() == p) {
        cout << "0\n";
        return;
    }
    for (int i = n - 1; i >= 0; --i) {
        if (a[i] < p - 1) {
            newDigit = a[i] + 1;
            break;
        }
    }
    int l = 0, r = p - 1;
    int x = a[n];
    while (l < r) {
        int m = (l + r) >> 1;
        bool res = false;
        if (x + m >= p) {
            if (check(digits, x + m + 1 - p, x - 1, true)) {
                res = true;
            }
        } else {
            if (check(digits, 0, x - 1, false) && check(digits, x + m + 1, p - 1, false)) {
                res = true;
            }
        }
        if (res) {
            r = m;
        } else {
            l = m + 1;
        }
    }
    cout << l << '\n';
}

